<script lang="ts">
	import { goto } from "$app/navigation";
	import { page } from "$app/state";
	import { createAuthFormOwner } from "$platform/auth-form-owner";
	import { buttonVariants } from "$lib/components/ui/button";
	import { Session } from "$lib/stores";
	import { cn } from "$lib/Utils";
	import { KeySquareIcon, LibraryIcon, Settings2Icon, SettingsIcon } from "@lucide/svelte";

	const { children } = $props();
	const routeOwner = createAuthFormOwner();

	const tabs: Record<
		string,
		{
			name: string;
			icon: any;
			hidden?: boolean;
		}
	> = $derived({
		preferences: {
			name: "Preferences",
			icon: Settings2Icon
		},
		library: {
			name: "Library",
			icon: LibraryIcon
		},
		identity: {
			name: "Public identity",
			icon: SettingsIcon
		},
		account: {
			name: "Account",
			icon: SettingsIcon,
			hidden: !$Session
		},
		client: {
			name: "API Clients",
			icon: KeySquareIcon,
			hidden: !$Session
		}
	});

	$effect(() => {
    page.url.href; tabs; const href = window.location.href;
    routeOwner.observe(href); const intent = routeOwner.capture();
    const key = new URL(href).pathname.split("/").at(-1)!;
    void Session.isValid().then(() => {
      if (!intent.alive()) return;
      const currentTabs = tabs;
      if (!(key in currentTabs) || currentTabs[key].hidden) goto(`/settings/${Object.keys(currentTabs)[0]}`, { replaceState: true });
    }).catch(() => { /* An unavailable/stale check cannot navigate this layout. */ });
  });
</script>

{#snippet navs()}
	<div class="border-b-2">
		<nav aria-label="Settings" class="text-muted-foreground/80 -mb-0.5 flex flex-nowrap overflow-auto whitespace-nowrap">
			{#each Object.entries(tabs) as [key, item]}
				{#if !item.hidden}
					{@const pathname = `/settings/${key}`}
					<a
						class={buttonVariants({
							class: cn("border-b-2 border-b-transparent !bg-transparent", {
								"border-accent": page.url.pathname === pathname
							}),
							variant: "ghost"
						})}
						class:!text-accent-foreground={page.url.pathname === pathname}
						href={pathname}
						aria-current={page.url.pathname === pathname ? "page" : undefined}
					>
						<item.icon />
						{item.name}
					</a>
				{/if}
			{/each}
		</nav>
	</div>
{/snippet}

<section class="mx-auto flex w-full max-w-200 flex-auto flex-col space-y-5">
	<header class="shrink-0">
		{@render navs()}
	</header>
	<div class="flex flex-auto flex-col">
		{#key JSON.stringify([page.url.pathname, page.url.searchParams.get("flow")])}
		{@render children?.()}
		{/key}
	</div>
</section>
